result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "md2html.py", "content": """"md2html: a Markdown-subset to HTML converter built on a real parser.

Architecture
------------
Two clearly separated stages:

1. Block parsing (``_parse_blocks``): splits the document into lines and
   recognizes block constructs -- ATX headings, fenced code blocks,
   unordered lists and paragraphs.  Blocks are delimited structurally
   (blank lines, fence lines, list markers), not by regex substitution
   over the whole document.

2. Inline parsing (``_InlineParser``): a recursive-descent parser over a
   single line/paragraph string.  It produces a small AST of nodes
   (Text, CodeSpan, Strong, Em, Link).  Nesting of ``**bold`` and
   ``*italic`` falls out of the recursion naturally, and code spans are
   parsed as opaque leaves, so no formatting is ever applied inside them.

All text content is HTML-escaped at the leaf level (``escape_text``);
attribute values (hrefs) are escaped with quoting enabled.
"""

from __future__ import annotations

import html
import re
import sys

__all__ = ["markdown_to_html", "render_inline"]


# --------------------------------------------------------------------------
# Escaping helpers
# --------------------------------------------------------------------------

def escape_text(s: str) -> str:
    """HTML-escape text content (&, <, >). Quotes stay readable in text."""
    return html.escape(s, quote=False)


def escape_attr(s: str) -> str:
    """HTML-escape an attribute value (&, <, >, \", ')."""
    return html.escape(s, quote=True)


# --------------------------------------------------------------------------
# Inline AST nodes
# --------------------------------------------------------------------------

class Text:
    def __init__(self, value: str) -> None:
        self.value = value

    def to_html(self) -> str:
        return escape_text(self.value)


class CodeSpan:
    def __init__(self, value: str) -> None:
        self.value = value

    def to_html(self) -> str:
        return "<code>{}</code>".format(escape_text(self.value))


class Strong:
    def __init__(self, children: list) -> None:
        self.children = children

    def to_html(self) -> str:
        return "<strong>{}</strong>".format("".join(c.to_html() for c in self.children))


class Em:
    def __init__(self, children: list) -> None:
        self.children = children

    def to_html(self) -> str:
        return "<em>{}</em>".format("".join(c.to_html() for c in self.children))


class Link:
    def __init__(self, children: list, url: str) -> None:
        self.children = children
        self.url = url

    def to_html(self) -> str:
        return '<a href="{0}">{1}</a>'.format(
            escape_attr(self.url), "".join(c.to_html() for c in self.children)
        )


# --------------------------------------------------------------------------
# Inline parser (recursive descent)
# --------------------------------------------------------------------------

_WHITESPACE = " \t\n"


class _InlineParser:
    """Recursive-descent parser for inline Markdown constructs.

    Supported: ``**strong**``, ``*em*`` (arbitrarily nested), `` `code` ``
    (opaque, no nested parsing), ``[label](url)`` links.  Everything else
    becomes literal (escaped) text.
    """

    def __init__(self, src: str) -> None:
        self.src = src

    def parse(self) -> list:
        nodes, _ = self._parse_nodes(0, None)
        return nodes

    # -- core --------------------------------------------------------------

    def _parse_nodes(self, i: int, stop):
        """Parse inline nodes from position ``i``.

        Stops at the delimiter ``stop`` ("**" or "*") if one is encountered
        at a position where it can act as a closing delimiter, or at end of
        input.  Returns ``(nodes, index)`` where ``index`` points at the
        stop delimiter, or at ``len(src)`` if none was found.
        """
        src = self.src
        n = len(src)
        nodes = []
        plain = []

        def flush():
            if plain:
                nodes.append(Text("".join(plain)))
                plain.clear()

        while i < n:
            if stop is not None and src.startswith(stop, i):
                if i > 0 and src[i - 1] not in _WHITESPACE:
                    break  # valid closing delimiter
            ch = src[i]

            if ch == "`":
                run = self._run_length(i, "`")
                j = self._find_run(i + run, "`", run)
                if j is not None:
                    flush()
                    nodes.append(CodeSpan(src[i + run:j]))
                    i = j + run
                else:  # unmatched backticks are literal
                    plain.append("`" * run)
                    i += run

            elif src.startswith("**", i):
                if self._can_open(i + 2):
                    children, end = self._parse_nodes(i + 2, "**")
                    if end < n and children:
                        flush()
                        nodes.append(Strong(children))
                        i = end + 2
                        continue
                plain.append("**")
                i += 2

            elif ch == "*":
                if self._can_open(i + 1):
                    children, end = self._parse_nodes(i + 1, "*")
                    if end < n and children:
                        flush()
                        nodes.append(Em(children))
                        i = end + 1
                        continue
                plain.append("*")
                i += 1

            elif ch == "[":
                link = self._try_link(i)
                if link is not None:
                    flush()
                    nodes.append(link)
                    i = link_end
                else:
                    plain.append("[")
                    i += 1

            else:
                plain.append(ch)
                i += 1

        flush()
        return nodes, i

    # -- helpers -----------------------------------------------------------

    @staticmethod
    def _run_length(i: int, ch: str) -> int:
        src = _InlineParser._src_for_runlength  # not used; kept simple below
        raise NotImplementedError

    def _can_open(self, pos: int) -> bool:
        """An emphasis delimiter can open only if not followed by whitespace."""
        return pos < len(self.src) and self.src[pos] not in _WHITESPACE

    def _find_run(self, start: int, ch: str, length: int):
        """Find the next run of exactly ``length`` occurrences of ``ch``."""
        src = self.src
        j = start
        while True:
            j = src.find(ch, j)
            if j == -1:
                return None
            k = j
            while k < len(src) and src[k] == ch:
                k += 1
            if k - j == length:
                return j
            j = k

    def _try_link(self, i: int):
        """Try to parse ``[label](url)`` starting at ``i``.

        Returns ``(Link, end_index)`` or ``None``.  The label may contain
        parentheses (brackets are tracked for one level of nesting); the
        URL runs to the first ``)``.
        """
        global link_end
        src = self.src
        depth = 0
        j = i + 1
        while j < len(src):
            c = src[j]
            if c == "[":
                depth += 1
            elif c == "]":
                if depth == 0:
                    break
                depth -= 1
            j += 1
        if j >= len(src) or src[j] != "]":
            return None
        if j + 1 >= len(src) or src[j + 1] != "(":
            return None
        close = src.find(")", j + 2)
        if close == -1:
            return None
        url = src[j + 2:close]
        if url.strip() == "" or "\n" in url:
            return None
        label = src[i + 1:j]
        children = _InlineParser(label).parse()
        link_end = close + 1
        return Link(children, url)


def render_inline(src: str) -> str:
    return "".join(node.to_html() for node in _InlineParser(src).parse())


# --------------------------------------------------------------------------
# Block parsing
# --------------------------------------------------------------------------

_HEADING_RE = re.compile(r"^(#{1,6})\s+(.+?)\s*$")
_LIST_ITEM_RE = re.compile(r"^\s*-\s+(.+?)\s*$")
_FENCE_OPEN_RE = re.compile(r"^```([^`\s]*)\s*$")


def _is_block_start(line: str) -> bool:
    return bool(
        line.strip() == ""
        or _HEADING_RE.match(line)
        or _LIST_ITEM_RE.match(line)
        or _FENCE_OPEN_RE.match(line)
    )


def _parse_blocks(lines: list) -> list:
    blocks = []
    i = 0
    n = len(lines)

    while i < n:
        line = lines[i]

        if line.strip() == "":
            i += 1
            continue

        fence = _FENCE_OPEN_RE.match(line)
        if fence:
            lang = fence.group(1)
            body = []
            i += 1
            # Only a line consisting solely of ``` terminates the fence;
            # a ``` occurring mid-line does NOT close the block.
            while i < n and lines[i].strip() != "```":
                body.append(lines[i])
                i += 1
            if i < n:  # consume closing fence (unterminated fences run to EOF)
                i += 1
            attr = ' class="language-{}"'.format(lang) if lang else ""
            content = escape_text("\n".join(body))
            if body:
                content += "\n"
            blocks.append("<pre><code{}>{}</code></pre>".format(attr, content))
            continue

        heading = _HEADING_RE.match(line)
        if heading:
            level = len(heading.group(1))
            blocks.append(
                "<h{0}>{1}</h{0}>".format(level, render_inline(heading.group(2)))
            )
            i += 1
            continue

        if _LIST_ITEM_RE.match(line):
            items = []
            while i < n:
                m = _LIST_ITEM_RE.match(lines[i])
                if not m:
                    break
                items.append(m.group(1))
                i += 1
            li = "\n".join("<li>{}</li>".format(render_inline(t)) for t in items)
            blocks.append("<ul>\n{}\n</ul>".format(li))
            continue

        # Paragraph: consume until a blank line or another block construct.
        para = [line]
        i += 1
        while i < n and not _is_block_start(lines[i]):
            para.append(lines[i])
            i += 1
        blocks.append("<p>{}</p>".format(render_inline("\n".join(para))))

    return blocks


# --------------------------------------------------------------------------
# Public API
# --------------------------------------------------------------------------

def markdown_to_html(markdown: str) -> str:
    """Convert a Markdown-subset document to an HTML string."""
    return "\n".join(_parse_blocks(markdown.splitlines()))


def main(argv: list) -> int:
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as fh:
            source = fh.read()
    else:
        source = sys.stdin.read()
    print(markdown_to_html(source))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
